// ============================================================
// Calculate Remaining —— 计算剩余分钟数，并合并回原始工单数据
// 和Day41/42的算法完全一样，只是这次多做一步"合并"
// ============================================================

// $json.ticket 是调用方整体传过来的工单对象
// 用一个新变量ticket接住，后面操作更清晰
const ticket = $json.ticket;

// DateTime.fromFormat(...) 把文本时间解析成Luxon的时间对象
// .diff($now, 'minutes').minutes 算出"距离现在还有多少分钟"
// Math.round(...) 四舍五入成整数分钟
const remaining_minutes = Math.round(
  DateTime.fromFormat(ticket.due_time, "yyyy-MM-dd HH:mm:ss").diff($now, 'minutes').minutes
);

// return的这一项里，用 ...ticket 展开原始工单的所有字段
// 展开语法（...）的意思是"把ticket对象里的每一个字段都摊平铺开"
// 再额外加一个新字段remaining_minutes
// 这样返回的数据 = 原始工单的全部字段 + 新算出来的remaining_minutes
// 调用方拿到结果后，原本的ticket_id/owner/priority等字段完全不会丢
return [
  {
    json: {
      ...ticket,
      remaining_minutes
    }
  }
];
